create table public.business_members (id uuid default gen_random_uuid() not null,business_id uuid not null,user_id uuid not null,role text default 'owner'::text not null,created_at timestamp with time zone default now() not null);
create table public.businesses (id uuid default gen_random_uuid() not null,owner_id uuid not null,name text not null,created_at timestamp with time zone default now() not null,stripe_account_id text,stripe_onboarding_complete boolean default false,stripe_charges_enabled boolean default false,onboarding_complete boolean default false,stripe_customer_id text,subscription_id text,subscription_status text,trial_ends_at timestamp with time zone);
create table public.crew_members (id uuid default gen_random_uuid() not null,name text not null,phone text,email text,role text default 'crew'::text,active boolean default true,created_at timestamp with time zone default now(),business_id uuid,pay_type text,pay_rate numeric);
create table public.customer_properties (id uuid default gen_random_uuid() not null,business_id uuid not null,customer_id uuid not null,label text default 'Property'::text not null,address text,city text,state text,zip text,notes text,created_at timestamp with time zone default now() not null);
create table public.customers (id uuid default gen_random_uuid() not null,name text not null,email text,phone text not null,address text,city text,state text,zip text,service_types text[] default '{}'::text[],notes text,archived boolean default false not null,created_at timestamp with time zone default now() not null,org_id uuid,created_by uuid,business_id uuid);
create table public.estimates (id uuid default gen_random_uuid() not null,customer_id uuid,job_id uuid,service_type text default 'lawn'::text not null,status text default 'draft'::text not null,line_items jsonb default '[]'::jsonb not null,notes text,total numeric(10,2) default 0 not null,follow_up_days integer default 3 not null,follow_up_sent_at timestamp with time zone,sent_at timestamp with time zone,expires_at timestamp with time zone,created_at timestamp with time zone default now() not null,tier text default 'none'::text,org_id uuid,business_id uuid);
create table public.expenses (id uuid default gen_random_uuid() not null,amount numeric not null,category text default 'other'::text not null,description text not null,date date not null,job_id uuid,notes text,created_at timestamp with time zone default now(),receipt_url text,org_id uuid,business_id uuid);
create table public.invoice_payments (id uuid default gen_random_uuid() not null,invoice_id uuid,amount numeric(10,2) not null,method text default 'cash'::text,note text,paid_at timestamp with time zone default now(),created_at timestamp with time zone default now(),business_id uuid);
create table public.invoices (id uuid default gen_random_uuid() not null,customer_id uuid,job_id uuid,estimate_id uuid,status text default 'draft'::text not null,line_items jsonb default '[]'::jsonb not null,notes text,total numeric(10,2) default 0 not null,card_on_file boolean default false not null,sent_at timestamp with time zone,due_at date,paid_at timestamp with time zone,created_at timestamp with time zone default now() not null,org_id uuid,business_id uuid);
create table public.job_media (id uuid default gen_random_uuid() not null,job_id uuid,customer_id uuid,org_id uuid,created_by uuid,tag text default 'general'::text not null,url text not null,file_name text,file_type text,notes text,created_at timestamp with time zone default now(),business_id uuid);
create table public.jobs (id uuid default gen_random_uuid() not null,customer_id uuid,service_type text default 'lawn'::text not null,title text not null,status text default 'scheduled'::text not null,scheduled_date date,scheduled_time time without time zone,duration_minutes integer default 60,assigned_to uuid,notes text,estimate_id uuid,invoice_id uuid,recurring text default 'none'::text not null,created_at timestamp with time zone default now() not null,org_id uuid,created_by uuid,price numeric(10,2),checklist jsonb default '[]'::jsonb,crew_member_ids uuid[] default '{}'::uuid[],business_id uuid);
create table public.services (id uuid default gen_random_uuid() not null,value text not null,label text not null,description text,color text,active boolean default true not null,created_at timestamp with time zone default now(),business_id uuid);
create table public.time_entries (id uuid default gen_random_uuid() not null,job_id uuid,crew_member_id uuid,clocked_in_at timestamp with time zone default now() not null,clocked_out_at timestamp with time zone,created_at timestamp with time zone default now(),break_type text,business_id uuid);